contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 setupAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint256 balBefore = address(c).balance;
        uint256 pot = c.winnersPot(); if (__ESBMC_reverted()) return;

        assert(pot == balBefore / 2);
    }

    receive() external payable {}
}

