// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 setupAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint256 balBefore = address(c).balance;
        uint256 pot;
        try c.winnersPot() returns (uint256 __r) { pot = __r; } catch { return; }
        assertTrue(pot == balBefore / 2);
    }

    function testFuzz_run(uint256 setupAmount) public {
        _run(setupAmount);
    }

    receive() external payable {}
}
